"""Two distinct editorial features calculated from the published row-level data."""
import csv,json,hashlib
from pathlib import Path
from urllib.parse import urlencode
from editorial_metrics import calculate
ROOT=Path(__file__).resolve().parents[1];DATA=ROOT/'data'
ORG={'seoul_city':'서울시 본청','seoul_council':'서울시의회','seoul_office':'사업소','seoul_fire':'소방'}
def read(name):
 with (DATA/name).open(encoding='utf-8-sig') as f:return list(csv.DictReader(f))
def render(page,hero,sec,table,H,bars):
 records=read('seoul-directory-records.csv');times=read('editorial-times.csv');m=calculate(records,times)
 (DATA/'editorial-2025.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
 (DATA/'editorial-calculations.py').write_bytes((ROOT/'tools/editorial_metrics.py').read_bytes())
 for key in ('organizations','districts','monthly','overlap','time_places','hours','office_extra'):
  with (DATA/f'editorial-{key}.csv').open('w',encoding='utf-8-sig',newline='') as f:
   w=csv.DictWriter(f,fieldnames=list(m[key][0]));w.writeheader();w.writerows(m[key])
 inputs={n:hashlib.sha256((DATA/n).read_bytes()).hexdigest() for n in ('seoul-directory-records.csv','editorial-times.csv','editorial-calculations.py')}
 (DATA/'editorial-manifest.json').write_text(json.dumps({'period':m['period'],'inputs':inputs,'selection':'Published directory, then calendar 2025; sensitivity reapplies five-document/three-month threshold within 2025','time_scope':'All 2025 published meal-labelled rows; exact raw join on document ID and parsed row; no attendees or purpose free text'},ensure_ascii=False,indent=2)+'\n')
 pct=lambda v:f'{v*100:.1f}%'
 def explore(label,**q):return '<a href="/seoul/?'+H(urlencode(q))+'">'+H(label)+'</a>'
