 common='<p class="note">분석 기간: 2025년 1월 1일~12월 31일. 상호를 미리 고르지 않은 공개 디렉터리 안의 기록입니다. 전체 서울 지출이나 모든 업소를 대표하지 않습니다. 주소·상호가 같은 표기 묶음이며 사업자 동일성·현재 영업·맛은 확인하지 않았습니다.</p>'
 downloads='<p><a href="/data/seoul-directory-records.csv">전체 입력 행 CSV</a> · <a href="/data/editorial-times.csv">식사 명시 시각 468행 CSV</a> · <a href="/data/editorial-2025.json">두 분석 전체 집계 JSON</a> · <a href="/data/editorial-calculations.py">표준 Python 계산 코드</a> · <a href="/data/editorial-manifest.json">입력 해시·범위</a></p><pre>python3 editorial-calculations.py seoul-directory-records.csv editorial-times.csv</pre>'
 methods='<p>원문 행의 문서 ID와 파싱 행 번호를 키로 중복을 제거한 공개 디렉터리에서 집행일이 2025년인 행만 사용했습니다. 서울 도로명·건물번호가 명확한 주소, 양의 정수 금액 300만원 이하, 2025~2026년 전체에서 서로 다른 문서 5개·집행 월 3개 이상인 묶음이 모집단입니다. 명백한 비식품 구매, 온라인 플랫폼·결제대행 주소, 불완전 주소, 업종·상호 모호 사례는 보류합니다. 카페 등 제외 규칙으로 일반적인 외식·구매 장소 전체를 포함하지 않습니다. <a href="/seoul/">전체 포함·제외 기준</a>과 <a href="/coverage.html">지역별 자료 범위</a>를 함께 확인하세요.</p>'
 a=hero('기관을 바꾸면, 다른 동네의 기록이 보입니다','서울시 본청만 보면 놓치는 장소를 찾는 법. 같은 2025년의 기록으로 기관별 주소 분포와 겹치는 후보를 비교했습니다.','서울 기록 길잡이 · 기관과 지역',meta='자료 분석·편집: 세금맛집 | 2026-10-23')+common
 a+=sec('본청에서 보이지 않는 사업소의 84개 주소 묶음', '<p>2025년에 관측된 969개 표기·주소 묶음 중 본청 기록에는 862개, 사업소 기록에는 290개가 있습니다. 두 집합의 공통 항목은 206개입니다. 따라서 사업소에만 있고 본청에는 없는 항목은 84개입니다. 이는 새로 생긴 업소 수가 아니라 <strong>기관 필터를 바꿔야 찾을 수 있는 기록</strong>의 차이입니다.</p><p>중구·종로구를 벗어난 후보를 찾을 때 본청의 건수순 목록부터 보는 방식은 이 자료에서 한계가 있습니다. 먼저 지역을 고르고 사업소·소방의 원문을 함께 살펴보는 경로가 유용합니다. 기관의 업무 위치가 차이를 만들었는지는 이 자료만으로 검증하지 않았습니다.</p>')
 a+=sec('동일한 12개월, 서로 다른 자료의 크기',table(['기관 범주','행 수','표기·주소 묶음','연결 문서','주소가 있는 구','식사 명시 행'],[[explore(ORG[r['organization']],year=2025,org=r['organization']),f"{r['rows']:,}",r['places'],r['documents'],r['districts'],r['meal_rows']] for r in m['organizations']])+'<p>네 범주 모두 12개월에 기록이 있지만 수집량은 같지 않습니다. 110행인 소방과 14,619행인 본청의 건수를 경쟁 순위로 비교하지 않습니다. 기관은 자료의 분류이며 사업소 하나하나를 동일 규모의 독립 기관으로 맞춘 비교가 아닙니다. 문서가 여러 장소를 포함하므로 장소별 문서 수를 더한 값도 아닙니다.</p>')
 a+=sec('중구·종로구 비중은 월별 가중치를 바꿔도 크게 달라지지 않습니다',table(['기관','전체 행 기준','12개월 비중의 단순 평균','2025년 안에서 반복 기준 재적용','재적용 행 수'],[[ORG[r['organization']],pct(r['central_share']),pct(r['equal_month_share']),pct(r['strict_2025_central_share']),f"{r['strict_2025_rows']:,}"] for r in m['organizations']])+'<p>전체 행 기준은 두 구의 행 수 ÷ 해당 기관의 전체 행 수입니다. 월별 단순 평균은 각 달 비중을 구한 뒤 12로 나누어 큰 달의 영향력을 줄였습니다. 반복 기준 재적용 비중은 2026년 기록 덕분에 반복 기준을 통과한 묶음의 영향을 점검하기 위해 2025년 자료만으로 문서 5개·월 3개 기준을 다시 적용한 결과입니다. 어느 계산도 누락된 문서를 복원하거나 기관 규모를 보정하지는 않습니다.</p><p><a href="/data/editorial-monthly.csv">48개 기관·월의 분자와 분모 CSV</a> · <a href="/data/editorial-organizations.csv">기관별 요약·민감도 CSV</a></p>')
 # One comparable visual: all institution shares use fixed 100% scale, with visible values.
 chart='<div class="chart" aria-label="기관별 중구·종로구 행 비중">'+''.join(f'<div class="barrow"><span>{ORG[r["organization"]]}</span><div class="bar-track"><div class="bar" style="width:{100*r["central_share"]:.4f}%"></div></div><b>{pct(r["central_share"])}</b></div>' for r in m['organizations'])+'</div><p class="small">막대의 전체 길이 = 100%. 바로 위 표와 같은 전체 행 기준입니다.</p>'
 a+=chart
 ds=sorted({r['district'] for r in m['districts']});orgorder=['seoul_city','seoul_council','seoul_office','seoul_fire'];lookup={(r['district'],r['organization']):r for r in m['districts']}
 a+=sec('내가 찾는 구에는 어느 자료가 있나요?', '<p>아래 숫자는 해당 구·기관에서 2025년에 한 번 이상 나타난 <strong>표기·주소 묶음 수</strong>입니다. 링크를 열면 그 조건의 실제 기록으로 이동합니다. 여러 기관에 등장한 장소는 각 열에 중복되므로 열을 합쳐 고유 장소 수로 읽지 마세요. 0은 이 선정 자료에서 관측되지 않았다는 뜻입니다.</p>'+table(['주소의 구']+[ORG[o] for o in orgorder],[[H(d)]+[explore(str(lookup[d,o]['places']),district=d,org=o,year=2025) if lookup[d,o]['places'] else '0' for o in orgorder] for d in ds])+'<p><a href="/data/editorial-districts.csv">구·기관별 행 수와 장소 수 CSV</a></p>')
 a+=sec('의회로 바꾸는 것과 사업소로 바꾸는 것은 다릅니다',table(['두 범주','공통 묶음','앞 범주에만','뒤 범주에만'],[[ORG[r['a']]+' / '+ORG[r['b']],r['intersection'],r['only_a'],r['only_b']] for r in m['overlap']])+'<p>본청·의회는 328개 묶음이 겹치고, 의회만 추가로 보여 주는 것은 11개입니다. 본청·사업소는 206개가 겹치며 사업소만 84개입니다. 따라서 중복된 후보를 반복해서 보는 대신 어떤 자료를 추가로 열면 탐색 범위가 넓어지는지 판단할 수 있습니다. 상호 띄어쓰기와 법인 접두어는 정규화했지만 유사 상호를 임의로 합치지 않아 같은 사업체가 여러 묶음일 가능성은 남아 있습니다.</p><p><a href="/data/editorial-overlap.csv">집합 교집합·합집합 CSV</a></p>')
 a+=sec('본청에서 놓친 84개 묶음을 직접 열어 보세요','<p>조건은 “2025년 사업소 기록 있음, 같은 해 본청 기록 없음”입니다. 의회·소방에도 등장할 수 있으므로 사업소에서만 이용한 업소라는 뜻은 아닙니다. 상호·주소순으로 제공하며 모든 항목은 해당 기관·연도의 기록과 공식 원문 사례에 연결합니다.</p><details><summary>84개 주소 목록 펼치기 · 추천 순위 아님</summary>'+table(['상호 / 주소','사업소 행','문서','식사 명시 행','기록 / 사례'],[[H(r['name'])+'<br><small>'+H(r['address'])+'</small>',r['rows'],r['documents'],r['meal_rows'],explore('조건에 맞는 기록',year=2025,org='seoul_office',place=r['place_id'])+' · <a href="'+r['source_url']+'">공식 원문</a>'] for r in sorted(m['office_extra'],key=lambda r:(r['name'],r['address']))])+'</details><p><a href="/data/editorial-office_extra.csv">84개 묶음과 원문 사례 CSV</a></p>')
 a+=sec('원문에서 시작하는 세 가지 지역 경로','<p>아래는 많은 기록 순으로 뽑은 추천이 아닙니다. 원문 표본에서 확인한 서로 다른 구의 식사 명시 기록을 시작점으로 고른 사례입니다. 같은 지역의 다른 후보는 표의 지역 링크로 넓혀 보세요.</p>'+table(['사례','주소','확인한 기록','해당 주소의 2025 식사 명시 기록'],[[H(r['name']),H(r['address']),f'<a href="{r["source_url"]}">{r["date"]} · {int(r["amount"]):,}원 원문</a>',explore('기록 열기',year=2025,purpose='meal',place=r['place_id'])] for r in audit['samples'] if r['stratum'] in ('지호한방삼계탕','화평동왕냉면','한촌설렁탕')]))
 a+=sec('계산 방법과 재현',methods+downloads)
 a+=sec('이 분석으로 답하지 못하는 것','<p>기관별 전체 예산, 누락 문서 수, 직원 수, 행정 서비스 인구를 분모로 쓰지 않았습니다. 따라서 어느 기관이 더 외식을 많이 하는지, 어떤 구가 인기 있는지 평가할 수 없습니다. 분모는 각 범주의 <strong>공개된 선정 행</strong>뿐입니다. 식사 명시가 아닌 간담회 등 용도 미확정 행도 포함한 지출 장소 분포입니다. 식사만 보려면 탐색기에서 목적을 바꾸세요.</p><p><a href="/analysis/recorded-times.html">다음 분석: 식사 명시 기록의 집행 시각으로 후보를 읽기 →</a></p>')
 page('analysis/institution-geography.html','기관을 바꾸면 달라지는 서울 장소 기록','같은 2025년의 17,117행에서 기관별 주소 분포와 장소 집합의 겹침을 계산하고 지역별 탐색 경로를 제공합니다.',a,True)
 b=hero('낮과 저녁, 원문에는 어떤 시각이 남았을까요?','2025년 식사 명시 468행의 집행 시각을 주소별로 묶었습니다. 운영시간을 추측하는 대신 과거 기록의 원문을 찾는 안내입니다.','서울 기록 길잡이 · 집행 시각',meta='자료 분석·편집: 세금맛집 | 2026-10-23')+common
 midday=sum(r['rows'] for r in m['hours'] if 11<=r['hour']<15);eve=sum(r['rows'] for r in m['hours'] if 17<=r['hour']<22);other=m['time_rows']-midday-eve
 b+=sec('식사 명시 기록 468행 중 356행은 11~14시에 적혀 있습니다',f'<p>전체 2025년 선정 지출 17,117행 중 원문에 식사가 명시된 것은 468행입니다. 이 행의 집행 시각을 원자료와 문서·행 번호로 연결했습니다. 468행 모두 날짜와 시·분 형식이 유효했습니다. 편집상 구간인 11:00~14:59에는 {midday}행, 17:00~21:59에는 {eve}행, 그 밖의 시각에는 {other}행이 있습니다. 범주별 행 수의 합은 468입니다.</p><p>이 결과는 점심 영업을 하는 업소의 비율이 아닙니다. 원문에 적힌 집행 시각은 예약·주문·입장·식사 종료 시간 중 어느 것인지 보장되지 않습니다. 식사 목적이 명시되지 않은 16,649행의 시각은 이 분석에서 제외했습니다. 현재 방문 가능 시간은 업소나 외부 지도에서 별도로 확인해야 합니다.</p>'+bars([(f'{r["hour"]:02}시',r['rows']) for r in m['hours'] if r['rows']])+table(['시각 구간','행 수','468행 중 비중'],[['11:00~14:59',midday,pct(midday/468)],['17:00~21:59',eve,pct(eve/468)],['그 밖',other,pct(other/468)]])+'<p class="small">시간별 막대는 최대 행 수에 맞춘 상대 길이입니다. 0행인 시간은 그림에서 생략했으며 CSV에는 0~23시를 모두 담았습니다.</p>')
 b+=sec('같은 “식사 명시”라도 남아 있는 시간대는 다릅니다','<p>참숯골의 17행은 모두 11~14시, 서민갈비살의 7행 중 6행은 17~21시입니다. 하지만 두 표본의 크기가 다르고 누락·목적 기재 방식도 같지 않습니다. “점심 맛집”이나 “저녁에만 이용”이라는 결론 대신, 내가 확인하려는 시간대의 <strong>과거 원문이 있는가</strong>를 묻는 데 사용하세요. 한 시간대가 0행이어도 그 시간에 영업하지 않는다는 뜻은 아닙니다.</p>')
 def time_detail(p):
  rs=sorted([r for r in times if r['place_id']==p['place_id']],key=lambda r:(r['date'],r['recorded_time'],r['source_id'],int(r['parsed_row'])))
  body=[]
  for r in rs:
   hour=int(r['hour']);band='11~14시' if 11<=hour<15 else '17~21시' if 17<=hour<22 else '그 밖'
   body.append(f'<tr data-time-source="{H(r["source_id"])}" data-time-row="{r["parsed_row"]}" data-time-place="{p["place_id"]}"><td>{r["date"]}</td><td><time>{r["recorded_time"]}</time></td><td>{band}</td><td>{H(ORG[r["organization"]])}</td><td>{int(r["amount"]):,}원</td><td><a href="{H(r["source_url"])}">공식 문서 · 파싱 행 {r["parsed_row"]}</a></td></tr>')
  return f'<details id="time-{p["place_id"]}"><summary>{H(p["name"])} · {H(p["address"])} · {p["rows"]}행 시각 펼치기</summary><p>2025년 원문에 식사 명시 · 11~14시 {p["midday"]}행 / 17~21시 {p["evening"]}행 / 그 밖 {p["other"]}행. 날짜·시각순입니다. 집행 시각은 영업시간이나 실제 방문 시각을 보증하지 않습니다.</p><div class="table-wrap" role="region" aria-label="{H(p["name"])} 날짜별 집행 시각" tabindex="0"><table><thead><tr><th scope="col">집행일</th><th scope="col">집행 시각</th><th scope="col">집계 구간</th><th scope="col">기관</th><th scope="col">집행액</th><th scope="col">원문</th></tr></thead><tbody>'+''.join(body)+'</tbody></table></div><p>'+explore('기간·기관별 기록도 비교하기',year=2025,purpose='meal',place=p['place_id'])+'</p></details>'
